mdl:
mdl 1;
create or modify published odata service MyFirstModule.CarOdataApi (
  Path: 'odata/carodataapi/v1/',
  Version: '1.0.0',
  ODataVersion: OData4,
  Namespace: 'DefaultNamespace',
  ServiceName: 'CarOdataApi',
  PublishAssociations: Yes,
  SupportsGraphQL: Yes,
  Authentication: (basic)
)
{
  publish entity MyFirstModule.VCar as 'VCars' (
    ReadMode: ReadFromDatabase,
    InsertMode: NotSupported,
    UpdateMode: NotSupported,
    DeleteMode: NotSupported
  )
  expose (
    ModelID as 'ModelID' (Filterable, Sortable, KEY),
    Brand as 'Brand' (Filterable, Sortable)
  );

};

grant access on published odata service MyFirstModule.CarOdataApi to MyFirstModule.User;
